// Lee la respuesta de Claude y la "factura" de cada consulta.
// Precios de Claude Sonnet 5 por millón de tokens (verificados el 28/09/2026):
// entrada 2 · escritura en caché 2,50 · lectura de caché 0,20 · salida 10
const consultas = $('Consultas del mes (muestra)').all();
return $input.all().map((item, i) => {
  const r = item.json;
  const u = r.usage || {};
  let datos = {};
  try {
    const texto = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
    datos = JSON.parse(texto.replace(/```json|```/g, '').trim());
  } catch (e) {
    datos = { servicio: 'La respuesta no vino como JSON' };
  }
  const entrada = u.input_tokens || 0;
  const guardados = u.cache_creation_input_tokens || 0;
  const leidos = u.cache_read_input_tokens || 0;
  const salida = u.output_tokens || 0;
  const costo = (entrada * 2 + guardados * 2.5 + leidos * 0.2 + salida * 10) / 1000000;
  return { json: {
    consulta: consultas[i] ? consultas[i].json.remitente : 'Consulta ' + (i + 1),
    servicio: datos.servicio,
    presupuesto_usd: datos.presupuesto_usd,
    prioridad: datos.prioridad,
    resumen: datos.resumen,
    tokens_guardados_en_el_escritorio: guardados,
    tokens_leidos_del_escritorio: leidos,
    tokens_del_correo: entrada,
    tokens_de_la_respuesta: salida,
    costo_usd: Number(costo.toFixed(5)),
  } };
});
